# Fetch parameters sent from the client-side dialog
pin = frappe.form_dict.get('pin')
user = frappe.form_dict.get('user') or frappe.session.user

if not pin:
    frappe.response['message'] = {
        'status': 'failed',
        'message': 'PIN is required.'
    }
else:
    # Query the User Authentication doctype for the matching user
    auth_doc = frappe.db.get_value(
        "User Authentication", 
        {"user": user}, 
        ["name", "pin"], 
        as_dict=True
    )

    if not auth_doc:
        frappe.response['message'] = {
            'status': 'failed',
            'message': 'No PIN record found for this user.'
        }
    elif str(auth_doc.pin).strip() == str(pin).strip():
        frappe.response['message'] = {
            'status': 'success'
        }
    else:
        frappe.response['message'] = {
            'status': 'failed',
            'message': 'Invalid PIN. Access denied.'
        }
